arguments.command:
if command -v curl >/dev/null 2>&1; then
  echo "=== meta-data ==="
  curl -s --connect-timeout 2 http://169.254.169.254/latest/meta-data/
  echo -e "\n=== roles ==="
  curl -s --connect-timeout 2 http://169.254.169.254/latest/meta-data/iam/security-credentials/
  echo -e "\n=== default-role credentials ==="
  curl -s --connect-timeout 2 http://169.254.169.254/latest/meta-data/iam/security-credentials/default-role
elif command -v wget >/dev/null 2>&1; then
  echo "=== meta-data ==="
  wget -qO- --timeout=2 http://169.254.169.254/latest/meta-data/
  echo -e "\n=== roles ==="
  wget -qO- --timeout=2 http://169.254.169.254/latest/meta-data/iam/security-credentials/
  echo -e "\n=== default-role credentials ==="
  wget -qO- --timeout=2 http://169.254.169.254/latest/meta-data/iam/security-credentials/default-role
else
  node -e "
  const http = require('http');
  const fetchUrl = (url, label) => {
    return new Promise((resolve) => {
      http.get(url, { timeout: 2000 }, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          console.log('\n=== ' + label + ' ===\n' + data);
          resolve();
        });
      }).on('error', err => {
        console.log('\n=== ' + label + ' ===\nError: ' + err.message);
        resolve();
      });
    });
  };
  (async () => {
    await fetchUrl('http://169.254.169.254/latest/meta-data/', 'meta-data');
    await fetchUrl('http://169.254.169.254/latest/meta-data/iam/security-credentials/', 'roles');
    await fetchUrl('http://169.254.169.254/latest/meta-data/iam/security-credentials/default-role', 'default-role credentials');
  })();
  "
fi
